window.jtpItemDescription=function(sku){return window.JTP_ITEM_DESCRIPTIONS[String(sku)]||'Descrição não encontrada na lista de itens';};
window.jtpApplyItemDescriptions=function(records){for(const record of records||[]){if(record.sku)record.name=window.jtpItemDescription(record.sku);}};
